use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf},collections::BTreeMap,process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/tripling-formation176";fn r(s:impl AsRef<Path>)->PathBuf{Path::new(R).join(s)}fn load(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let kind=std::env::args().nth(1).unwrap();assert!(["probe","oracle"].contains(&kind.as_str()));let info=load(r("frozen-ON.json"));let frozen=r("frozen/ON");let mut pins:BTreeMap<String,String>=serde_json::from_value(info["input_pins"].clone()).unwrap();for(p,h)in&pins{assert_eq!(hash(p),*h);}let mut argv=vec!["--edition=2021".to_string(),"-O".into(),"-C".into(),"target-cpu=native".into(),"-C".into(),"lto=fat".into(),"-C".into(),"codegen-units=1".into(),"-L".into(),format!("dependency={}",frozen.display())];for(n,p)in info["libraries"].as_object().unwrap(){argv.extend(["--extern".into(),format!("{n}={}",p.as_str().unwrap())]);}if kind=="probe"{let sha=fs::read_dir(&frozen).unwrap().map(|e|e.unwrap().path()).filter(|p|p.file_name().unwrap().to_string_lossy().starts_with("libsha2-")&&p.extension().unwrap()=="rlib").collect::<Vec<_>>();assert_eq!(sha.len(),1);argv.extend(["--extern".into(),format!("sha2={}",sha[0].display())]);for f in["probe.rs","perf.rs"]{pins.insert(r(f).display().to_string(),hash(r(f)));}}else{let deps="/home/ubuntu/src/zopro-perf-work/absolute-norm176/target-off/release/deps";argv.extend(["-L".into(),format!("dependency={deps}")]);for name in["ark_bn254","ark_ec","ark_ff"]{let files=fs::read_dir(deps).unwrap().map(|e|e.unwrap().path()).filter(|p|p.file_name().unwrap().to_string_lossy().starts_with(&format!("lib{name}-"))&&p.extension().unwrap()=="rlib").collect::<Vec<_>>();assert_eq!(files.len(),1);argv.extend(["--extern".into(),format!("{name}={}",files[0].display())]);}for e in fs::read_dir(deps).unwrap(){let p=e.unwrap().path();if p.extension().is_some_and(|s|s=="rlib"||s=="so"){pins.insert(p.display().to_string(),hash(p));}}pins.insert(r("oracle.rs").display().to_string(),hash(r("oracle.rs")));}argv.extend([r(format!("{kind}.rs")).display().to_string(),"-o".into(),r(&kind).display().to_string()]);let v=json!({"argv":argv,"input_pins":pins});fs::write(r(format!("link-{kind}.json")),serde_json::to_vec_pretty(&v).unwrap()).unwrap();assert!(Command::new("rustc").args(&argv).status().unwrap().success());let metadata=json!({"binary":r(&kind),"sha256":hash(r(&kind)),"input_pins":pins,"native_flags":info["rustflags"],"lto":"fat","codegen_units":1,"link_command":v});fs::write(r(format!("{kind}.json")),serde_json::to_vec_pretty(&metadata).unwrap()).unwrap();println!("Linked{kind} nativeO3fatLTO1CGU with{}pins",pins.len());}
